package tacticalplan

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"sync"
)

// ProReferenceMinPlayers is how many qualifying players a library's own pro
// demos need before they replace the bundled reference.
const ProReferenceMinPlayers = 10

// proReferenceJSON is measured professional play, regenerated by
// TestGenerateProReference; its description names the matches it read.
//
//go:embed pro_reference_default.json
var proReferenceJSON []byte

// ProReferenceMatch names one map the bundled reference was measured on.
type ProReferenceMatch struct {
	Map    string   `json:"map"`
	Teams  []string `json:"teams"`
	Rounds int      `json:"rounds"`
}

// ProReferenceRow is one professional player's line over the reference matches.
type ProReferenceRow struct {
	SteamID64 string             `json:"steamid64"`
	Name      string             `json:"name"`
	Team      string             `json:"team"`
	Rounds    int                `json:"rounds"`
	Matches   int                `json:"matches"`
	Values    map[string]float64 `json:"values"`
}

// ProReferenceMap is the reference of one map with enough players.
type ProReferenceMap struct {
	Baseline Baseline          `json:"baseline"`
	Players  []ProReferenceRow `json:"players"`
}

// ProReference is the professional reference Studio ships, so the Pro
// comparison works before any pro demo is imported.
type ProReference struct {
	ID          string `json:"id"`
	Description string `json:"description"`
	// UpdatedAt is when a server-built reference was measured; empty when bundled.
	UpdatedAt string                     `json:"updated_at,omitempty"`
	Matches   []ProReferenceMatch        `json:"matches"`
	Baseline  Baseline                   `json:"baseline"`
	Players   []ProReferenceRow          `json:"players"`
	Maps      map[string]ProReferenceMap `json:"maps"`
}

var loadProReference = sync.OnceValue(func() ProReference {
	ref, err := DecodeProReference(proReferenceJSON)
	if err != nil {
		panic("tacticalplan: embedded pro reference is invalid: " + err.Error())
	}
	return ref
})

// DefaultProReference returns the bundled reference. Callers must not change
// its maps: every caller shares them.
func DefaultProReference() ProReference {
	return loadProReference()
}

// DecodeProReference reads a reference and rejects one missing a metric, so a
// truncated file fails at load instead of comparing against zeros.
func DecodeProReference(b []byte) (ProReference, error) {
	var ref ProReference
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&ref); err != nil {
		return ProReference{}, fmt.Errorf("decode pro reference: %w", err)
	}
	if err := ref.validate(); err != nil {
		return ProReference{}, err
	}
	return ref, nil
}

func (r ProReference) validate() error {
	if r.Description == "" || len(r.Players) == 0 {
		return errEmptyProReference
	}
	for _, metric := range ReferenceMetrics {
		if v := r.Baseline.Metrics[metric]; v.Players == 0 || v.PriorStddev <= 0 {
			return fmt.Errorf("pro reference metric %s has no players or no spread", metric)
		}
	}
	return nil
}

// Spread is what a library baseline borrows from the reference.
func (r ProReference) Spread() ReferenceSpread {
	out := ReferenceSpread{RoundStddev: map[string]float64{}, PriorStddev: map[string]float64{}}
	for metric, v := range r.Baseline.Metrics {
		out.RoundStddev[metric] = v.RoundStddev
		out.PriorStddev[metric] = v.PriorStddev
	}
	return out
}

// For returns the reference of a map, or of every map when the map has no
// entry of its own; the returned baseline names the map it read.
func (r ProReference) For(mapName string) (Baseline, []ProReferenceRow, string) {
	if m, ok := r.Maps[mapName]; ok && mapName != "" {
		return m.Baseline, m.Players, mapName
	}
	return r.Baseline, r.Players, ""
}

// ProLeaderboard ranks reference rows on one metric like BaselineSample.Leaderboard.
// Rows hold the reference metrics and kd, which kills and deaths per round give;
// the rating needs assists per round, which the reference does not keep, so a
// rating board over reference rows is empty.
func ProLeaderboard(rows []ProReferenceRow, metric string, minRounds, limit int) []LeaderboardRow {
	out := []LeaderboardRow{}
	for _, row := range rows {
		values := referenceValues(row.Values)
		v, ok := values[metric]
		if row.Rounds < minRounds || !ok {
			continue
		}
		out = append(out, LeaderboardRow{SteamID64: row.SteamID64, Name: row.Name, Team: row.Team, Rounds: row.Rounds, Matches: row.Matches, Value: v, Metrics: values})
	}
	return rankRows(out, metric, limit)
}

// referenceValues is a reference row's metrics with kd added when deaths per round are known.
func referenceValues(values map[string]float64) map[string]float64 {
	out := make(map[string]float64, len(values)+1)
	for k, v := range values {
		out[k] = v
	}
	if dpr := values[MetricDPR]; dpr > 0 {
		out[MetricKD] = round4(values[MetricKPR] / dpr)
	}
	return out
}

// rankRows orders rows best first, ties by rounds then id, and numbers them.
func rankRows(rows []LeaderboardRow, metric string, limit int) []LeaderboardRow {
	lower := LowerIsBetter(metric)
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].Value != rows[j].Value {
			return (rows[i].Value < rows[j].Value) == lower
		}
		if rows[i].Rounds != rows[j].Rounds {
			return rows[i].Rounds > rows[j].Rounds
		}
		return rows[i].SteamID64 < rows[j].SteamID64
	})
	if limit > 0 && len(rows) > limit {
		rows = rows[:limit]
	}
	for i := range rows {
		rows[i].Rank = i + 1
	}
	return rows
}
